                        label={i === 0 ? 'Increment' : ''}
                        type="number"
                        min={1}
                        step={1}
                        value={tier.increment}
                        placeholder="e.g. 25"
                        onChange={(e) => {
                          const next = [...tiers]
                          next[i] = { ...tier, increment: e.target.value }
                          setTiers(next)
                          setDirty(true)
                        }}
                      />
                    </div>
                    <button
                      type="button"
                      onClick={() => {
                        setTiers(tiers.filter((_, idx) => idx !== i))
                        setDirty(true)
                      }}
                      className={`text-surface-500 hover:text-red-400 transition-colors ${i === 0 ? 'mt-5' : ''}`}
                    >
                      <Trash2 className="w-4 h-4" />
                    </button>
                  </div>
                ))}
              </div>
              {errors.tiers && <p className="text-xs text-red-400">{errors.tiers}</p>}
              <Button
                variant="secondary"
                size="sm"
                onClick={() => {
                  setTiers([...tiers, { upTo: '', increment: '10' }])
                  setDirty(true)
                }}
              >
                <Plus className="w-3.5 h-3.5 mr-1" />
                Add tier
              </Button>
            </div>
          )}
        </div>

        <div className="grid grid-cols-1 sm:grid-cols-2 gap-4 mt-4">
          <Input
            label="Start time""}

