 * Publish action permission tests for PublicationListPage and ReviewDetailPage.
 *
 * Verifies that:
 *   - The Publish button is visible only to Administrator (who has managePublications)
 *   - ContentEditor does NOT see the Publish button (has createPublication, not managePublications)
 *   - ReviewerApprover does NOT see the Publish button
 *   - ContentEditor DOES see Edit / New Publication buttons (createPublication)
 *   - ReviewerApprover DOES see the Review button (approvePublication)
 *
 * Evidence: src/pages/publishing/PublicationListPage.tsx (canPublish),
 *           src/pages/publishing/ReviewDetailPage.tsx (canPublish),
 *           src/services/publicationService.ts:299 (requirePermission('managePublications')),
 *           src/auth/permissions.ts (ROLE_PERMISSIONS)
 */

import { act, render, screen } from '@testing-library/react'
import { describe, it, expect, vi, beforeEach } from 'vitest'
import { useAuthStore } from '@/store/authStore'
import { Role } from '@/types'
import type { Publication } from '@/types'

// ── Stub heavy deps ───────────────────────────────────────────────────────────

vi.mock('@/db', () => ({
  db: {
    publications: {
      orderBy: () => ({ reverse: () => ({ toArray: async () => [] }) }),
      get: async (_id: string) => mockPub,
    },
    publicationVersions: {
      where: () => ({ equals: () => ({ sortBy: async () => [] }) }),
    },
  },
}))

vi.mock('@/services/publicationService', () => ({
  publishPublication: vi.fn(),
  approvePublication: vi.fn(),
  rejectPublication: vi.fn(),
  rollbackToVersion: vi.fn(),
}))

vi.mock('@/utils/sanitize', () => ({
  sanitizeHtml: (s: string) => s,
}))

