  id: 'pub-1',
  title: 'Test Publication',
  type: 'Announcement',
  body: '<p>Body</p>',
  status: 'Approved',
  audienceRoles: [],
  audienceOrgs: [],
  audienceTags: [],
  moderationFlags: [],
  moderationStatus: 'Pending',
  createdBy: 'admin-1',
  createdAt: Date.now() - 10_000,
  updatedAt: Date.now() - 1_000,
}

// ── Role helper ───────────────────────────────────────────────────────────────

function setRole(role: Role) {
  useAuthStore.setState({
    currentUser: {
      id: `user-${role}`,
      username: role.toLowerCase(),
      displayName: role,
      role,
      isActive: true,
      createdAt: Date.now(),
    },
  } as Parameters<typeof useAuthStore.setState>[0])
}

// ── PublicationListPage — Publish button visibility ───────────────────────────

describe('PublicationListPage — Publish button visibility', () => {
  beforeEach(() => {
    vi.resetModules()
  })

  it('shows Publish button to Administrator (has managePublications)', async () => {
    setRole(Role.Administrator)
    const { PublicationListPage } = await import(
      '@/pages/publishing/PublicationListPage'
    )
    await act(async () => {
      render(<PublicationListPage />)
    })
    // Administrator should see the Publish button for the Approved publication
    expect(screen.queryByText('Publish')).not.toBeNull()
  })

  it('does NOT show Publish button to ContentEditor (lacks managePublications)', async () => {
    setRole(Role.ContentEditor)
    const { PublicationListPage } = await import(
      '@/pages/publishing/PublicationListPage'
    )
    await act(async () => {
      render(<PublicationListPage />)
    })
    expect(screen.queryByText('Publish')).toBeNull()
  })

  it('does NOT show Publish button to ReviewerApprover (lacks managePublications)', async () => {
    setRole(Role.ReviewerApprover)
    const { PublicationListPage } = await import(
      '@/pages/publishing/PublicationListPage'
    )
    await act(async () => {
      render(<PublicationListPage />)
    })
    expect(screen.queryByText('Publish')).toBeNull()
  })
})

// ── ReviewDetailPage — Publish button visibility ──────────────────────────────

describe('ReviewDetailPage — Publish button visibility', () => {
  beforeEach(() => {
    vi.resetModules()
  })

  it('shows Publish button to Administrator (has managePublications)', async () => {
    setRole(Role.Administrator)
    const { ReviewDetailPage } = await import(
      '@/pages/publishing/ReviewDetailPage'
    )
    await act(async () => {
      render(<ReviewDetailPage publicationId="pub-1" />)
    })
    expect(screen.queryByText('Publish')).not.toBeNull()
  })

  it('does NOT show Publish button to ContentEditor (lacks managePublications)', async () => {
    setRole(Role.ContentEditor)
    const { ReviewDetailPage } = await import(
      '@/pages/publishing/ReviewDetailPage'
    )
