151	// ── Review panel (per-item expandable) ────────────────────────────────────────
152	
153	interface ReviewPanelProps {
154	  item: CatalogItem
155	  currentUserId: string
156	  currentUserName: string
157	}
158	
159	function ReviewPanel({ item, currentUserId, currentUserName }: ReviewPanelProps) {
160	  const [reviews, setReviews] = useState<CatalogReview[]>([])
161	  const [myReview, setMyReview] = useState<CatalogReview | null>(null)
162	  const [isLoading, setIsLoading] = useState(true)
163	  const [rating, setRating] = useState(0)
164	  const [comment, setComment] = useState('')
165	  const [submitting, setSubmitting] = useState(false)
166	
167	  useEffect(() => {
168	    const load = async () => {
169	      const [approved, mine] = await Promise.all([
170	        listItemReviews(item.id),
171	        getMyReview(item.id, currentUserId),
172	      ])
173	      setReviews(approved)
174	      setMyReview(mine)
175	      if (mine) {
176	        setRating(mine.rating)
177	        setComment(mine.comment)
178	      }
179	      setIsLoading(false)
180	    }
181	    void load()
182	  }, [item.id, currentUserId])
183	
184	  const handleSubmit = async () => {
185	    if (rating === 0) { toast.error('Please select a rating'); return }
186	    if (!comment.trim()) { toast.error('Please enter a comment'); return }
187	    setSubmitting(true)
188	    try {
189	      const result = await submitReview(item.id, rating, comment.trim(), currentUserId, currentUserName)
190	      setMyReview(result)
191	      if (result.status === 'Flagged') {
192	        toast.warning('Review submitted but contains flagged content — awaiting moderator review')
193	      } else {
194	        toast.success('Review submitted')
195	      }
196	      // Refresh approved list
197	      const approved = await listItemReviews(item.id)
198	      setReviews(approved)
199	    } catch (err) {
200	      toast.error(err instanceof Error ? err.message : 'Failed to submit review')
201	    } finally {
202	      setSubmitting(false)
203	    }
204	  }
205	
206	  if (isLoading) {
207	    return <p className="text-xs text-surface-600 py-2">Loading reviews…</p>
208	  }
209	

